# -*- coding: utf-8 -*-
"""MANAPRINT — WOWOWO! (création RANIHEI SISTERS & SHOP) · maquette CANVA de Maeva
(26/11/2026, « wowowo_canva_12_A4 ») reprise TELLE QUELLE : 12 billets / feuille A4 PAYSAGE
(3 colonnes x 4 rangées), traits de coupe en pointillés. Chaque billet : cadre arrondi,
la mamie aux fruits (image de la maquette, rangée aussi DANS ce fichier), « WOWOWO! »,
9 ÉTOILES (3 x 3) et « RANIHEI SISTERS & SHOP 87 77 39 19 ».
Maquette « wowowo_30pt_12_A4 » (26/11) : UN numéro par étoile, 30 pt.
RÈGLE (26/11, Maeva : « mettre les plages ») — une plage par étoile, dans l'ordre de lecture :
   1-8 · 9-16 · 17-25 · 26-33 · 34-41 · 42-50 · 51-58 · 59-66 · 67-75  -> crieur 1 à 75.
   La plage est écrite en petit au-dessus du chiffre, dans l'étoile.
Le dessin est enregistré une seule fois par document (fichier léger, impression d'une traite).
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""
import io, os as _os, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import landscape, A4
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
GRIS = colors.Color(.45, .45, .45)
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM, T_NUM = "Helvetica-Bold", 30
T_PLAGE_NUM = 24      # 24 pt : la plage tient au-dessus du chiffre, dans l'étoile
_XS = (126.4206, 185.9482, 245.4757)
_YS = (91.02378, 56.4411, 21.85843)
_MAMIE = (6.23622, 9.92126, 86.45669, 129.8268)
PLAGES = [(1, 8), (9, 16), (17, 25), (26, 33), (34, 41), (42, 50), (51, 58), (59, 66), (67, 75)]
_IMG = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "wowowo_v2_mamie.png")

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _source_png():
    if _os.path.exists(_IMG):
        return _IMG
    import base64
    return base64.b64decode(_MAMIE_PNG)


def _numeros(rng):
    for _ in range(400):
        t = tuple(rng.randint(lo, hi) for lo, hi in PLAGES)
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_wowowo_modele", False):
        return
    b = _DESSIN_B.replace("{H}", c._doc.getInternalFontName("Helvetica"))
    c.beginForm("WOWOWO_DESSIN", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n" + _DESSIN_A)
    x, y, w, h = _MAMIE
    _masque.poser(c, "WOWOWO_MAMIE", _source_png(), x, y, w, h)
    c._code.append(b + "\nQ")
    c.endForm()
    c._wowowo_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("WOWOWO_DESSIN")
    _txt(c, "RANIHEI SISTERS & SHOP 87 77 39 19", 145.0371, 8.503937, "Helvetica-Bold", 4.4, NOIR)
    _txt(c, "N\u00b0 %06d" % serie, 100.0, 8.503937, "Helvetica", 4.4, GRIS)
    for k, v in enumerate(nums):
        x, y = _XS[k % 3], _YS[k // 3]
        _txt(c, str(v), x, y + 0.8, POLICE_NUM, T_PLAGE_NUM, col, centre=True)
        lo, hi = PLAGES[k]
        _txt(c, "%d-%d" % (lo, hi), x, y + 19.6, "Helvetica-Bold", 4.6, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    rng = random.Random(int(serie_start) * 100003 + 6060)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        entete = "  \u00b7  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 6)
        c.drawRightString(PAGE_W - DECAL_X, DECAL_Y / 2.0 - 2, "page %d" % no_page)

        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, _numeros(rng), col)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in (1, 2):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in (1, 2, 3):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


